"""Approved public Workshop pages. No membership or public profiles are simulated."""
from html import escape

SERVICES = [('tools','Using the tools'),('timeline','Timeline organization'),('evidence_dossier','Evidence organization'),('affidavit_formatting','Affidavit formatting'),('training','Learning and training'),('independent_review','Independent review interest')]

def options(values):
    return ''.join(f'<option value="{value}">{escape(label)}</option>' for value,label in values)

def application_form(kind):
    assistance=kind=='assistance'
    role='' if assistance else '<div class="field"><label for="kind">How would you like to contribute?</label><select id="kind" name="kind"><option value="reviewer">Independent reviewer applicant</option><option value="witness">Independent observation volunteer</option></select></div>'
    support='<div class="field"><label for="requested-support">Support requested</label><select id="requested-support" name="requested_support"><option value="free">Free help</option><option value="discounted">Discounted help</option></select></div>' if assistance else ''
    profession='' if assistance else '<div class="field"><label for="profession">Professional background (optional)</label><select id="profession" name="profession">'+options([('prefer_not_to_say','Prefer not to say'),('engineering','Engineering'),('education','Education'),('research','Research'),('administration','Administration'),('community','Community work'),('other','Another field')])+'</select><p class="field-hint">Self-described interests. This does not verify qualifications.</p></div>'
    availability='' if assistance else '<div class="field"><label for="availability">Broad availability (optional)</label><select id="availability" name="availability">'+options([('unsure','Not sure yet'),('occasional','Occasional'),('monthly','About once a month'),('weekly','About once a week')])+'</select><p class="field-hint">No exact schedule or location needed.</p></div>'
    path='/community/assistance' if assistance else '/community/reviewers'
    return f'''<section class="panel application-panel"><p class="tag">Private request · Adults 18+</p><h2>{'Ask about support' if assistance else 'Apply to contribute'}</h2><p>We will send a private confirmation link. Confirming your email places this application in the human review process.</p><form data-application="{kind}" data-application-source="{path}"><div class="field"><label for="application-email">Email address</label><input id="application-email" name="email" type="email" autocomplete="email" maxlength="254" required><p class="field-hint">For this application only. No newsletter subscription.</p></div><div class="field"><label for="display-alias">Preferred name or alias (optional)</label><input id="display-alias" name="display_alias" type="text" autocomplete="off" maxlength="60"><p class="field-hint">A legal name is not required. Use an alias without private details.</p></div>{role}<div class="field"><label for="service-interest">Main area of interest</label><select id="service-interest" name="service_interest">{options(SERVICES)}</select></div>{support}{profession}{availability}<fieldset class="acknowledgements"><legend>Before you submit</legend><label class="check"><input id="application-adult" name="adult" type="checkbox" required><span>I am 18 or older.</span></label><label class="check"><input name="privacy_acknowledged" type="checkbox" required><span>I understand this private application requests only minimal contact and preference information. I will not submit private case records, financial documents, government identifiers or other sensitive documents. Kapukai may contact me about this application. <a href="/community/privacy/#applications">Read the application privacy notice.</a></span></label><label class="check"><input name="human_review_acknowledged" type="checkbox" required><span>I understand confirmation requests human review. Assistance depends on capacity and suitability; a volunteer application is not a credential, appointment or approval. Engineering and document formatting are not legal advice.</span></label></fieldset><div class="hp" aria-hidden="true"><label>Website<input name="website" tabindex="-1" autocomplete="off"></label></div><button type="submit" class="full">Send my confirmation link</button><p id="application-status" class="status" role="status" aria-live="polite"></p></form><noscript><p>This form requires JavaScript. Email <a href="mailto:architect@kapukai.org">architect@kapukai.org</a> to ask how to apply. Please do not include private case details.</p></noscript><p class="small">Do not provide pay stubs, identity documents, case files, private addresses or names of children. There is no upload field.</p></section>'''

def build_workshop(page):
    page('', 'The Workshop', 'Learn, contribute and request support through Kapukai. Community accounts and shared discussion spaces are planned; current invitations are separate, private choices.', '''<section class="workshop-hero"><div><p class="eyebrow">Kapukai Governance Lab · The Workshop</p><h1>Find a useful next step.<br>Build it together.</h1><p class="lede">Tools, learning and practical contributions for public decisions people can inspect, question and correct.</p><div class="actions"><a class="button" href="/join/">Choose how to take part</a><a class="button secondary" href="/community/assistance/">Ask about free or discounted help</a></div><p class="small">Choose your interests privately. No payment or case files to join an interest list.</p></div><aside class="hero-note"><p class="tag">Start with what is useful</p><h2>A place to learn.<br>A way to contribute.</h2><p>We are building the Workshop in stages. Interest lists and applications come first; member accounts, discussion rooms and matching are not open yet.</p><a href="/community/lifecycle/">See how participation works →</a></aside></section>
<section class="section-block" id="participate"><div class="section-heading"><div><p class="eyebrow">One Workshop · Three shared spaces</p><h2>Room to learn and connect.</h2></div><span class="state-pill">Spaces planned</span></div><div class="cards three"><article class="panel"><p class="card-number">01</p><h3>Welcome &amp; connections</h3><p>Find common interests and a clear first step. Membership and public visibility will be separate choices.</p><a href="/join/">Register your interest</a></article><article class="panel"><p class="card-number">02</p><h3>Tools &amp; feedback</h3><p>Use fictional practice cases. Describe what works, what breaks and what would make a meaningful improvement.</p><a href="/testers/">Apply for tester invitations</a></article><article class="panel"><p class="card-number">03</p><h3>Learning circle</h3><p>Classes, webinars and guided practice. Learn at your pace as sessions and resources become available.</p><a href="/community/learn/">Explore learning</a></article></div></section>
<section class="section-block" id="tools"><p class="eyebrow">Tools &amp; support</p><h2>Start safely. Keep the scope clear.</h2><div class="cards"><article class="panel"><h3>Practice before sharing real records</h3><p>Download fictional cases and expected results to test attribution, timelines and corrections. No signup needed.</p><a class="button" href="/community/practice/">Get free practice material</a></article><article class="panel"><h3>Need help accessing the work?</h3><p>Ask about free or discounted assistance. We start with a small application and human review. No income documents required at this stage.</p><a class="button secondary" href="/community/assistance/">Apply for support</a></article></div></section>
<section class="section-block"><div class="callout"><div><p class="eyebrow">Independent contribution</p><h2>Offer careful review or observation.</h2><p>Express interest in a defined reviewer or witness role. Training, conflicts, consent and the limits of an assignment must be agreed before any work begins.</p></div><a class="button" href="/community/reviewers/">Apply to contribute</a></div></section>
<section class="featured-article" id="explore"><div><p class="eyebrow">Explore · The Remedy Brief</p><h2>When power causes harm, people need a way to push back.</h2><p>Read Christine’s article about accountability and the engineering of inspectable evidence.</p><a href="/articles/tort-law-and-accountability/">Read the article →</a></div><blockquote>Code can make an argument reproducible. It cannot make an unsupported argument true.</blockquote></section>''',False)
    page('community/assistance','Free and discounted assistance','Request free or discounted Kapukai engineering and tool support. No private case files or income documents at this stage.', '''<div class="layout"><section><p class="eyebrow">Access within our capacity</p><h1>Cost should not end the conversation.</h1><p class="lede">Ask about free or discounted help with tools, learning or engineering support. A person reviews each confirmed application.</p><ol class="steps"><li><strong>Tell us the kind of help you need.</strong><br>Choose a broad topic. You do not need to explain a personal case.</li><li><strong>Confirm your email.</strong><br>Opening the link alone does not submit the confirmed application. Review it and choose Confirm.</li><li><strong>Wait for a human response.</strong><br>We will discuss what is possible within available capacity before you decide whether to proceed.</li></ol><div class="notice"><strong>No proof of hardship required at this stage.</strong><br>No pay stubs, ID scans or private records. Testing, volunteering, publicity and positive feedback are not conditions of assistance.</div><p>Possible support may begin with learning resources or a limited tool test. Engineering time, independent review and other services depend on scope and capacity. There is no promised turnaround.</p><p class="small">Kapukai provides engineering and formatting support, not legal advice or representation. Nothing here extends a filing deadline or arranges emergency assistance.</p></section>'''+application_form('assistance')+'</div>','applications.js')
    page('community/reviewers','Independent reviewers and witnesses','Express interest in independent review or observation. Applications do not confer credentials, expert status or an assignment.', '''<div class="layout"><section><p class="eyebrow">Careful work · Clear limits</p><h1>Contribute what you can responsibly observe.</h1><p class="lede">Apply to help with independent review, source checking or a defined observation role.</p><div class="panel"><h2>Two different roles</h2><h3>Independent reviewer applicant</h3><p>Express interest in checking a defined process, source or output. Relevant training, competence and conflicts must be assessed for each assignment.</p><h3>Independent observation volunteer</h3><p>Document what you personally observed within an agreed scope. Hearing someone describe an event does not establish that the event occurred.</p></div><ol class="steps"><li><strong>Apply without private case information.</strong><br>A professional category and broad availability are enough to start.</li><li><strong>Confirm your email.</strong><br>This starts human review, not an assignment.</li><li><strong>Agree the scope before participating.</strong><br>Training, conflicts, confidentiality, participant consent and supervision are separate onboarding steps.</li></ol><p class="small">Submitting this form does not certify you as an expert, appoint you as a court officer, or guarantee that a statement will be accepted by a court. No private records are shared through this application.</p></section>'''+application_form('reviewer')+'</div>','applications.js')
    page('community/learn','Classes, webinars and guided practice','Register interest in Kapukai free classes and webinars. Dates and class registration will be announced separately.', '''<p class="eyebrow">The learning circle</p><h1>Understand the process.<br>Practice the skills.</h1><p class="lede">Free classes and webinars are being developed. Choose class notices if you would like dates and registration details when they are ready.</p><div class="actions"><a class="button" href="/join/#signup">Get class and webinar notices</a><a class="button secondary" href="/community/practice/">Practice now without signing up</a></div><div class="notice"><strong>No classes are scheduled on this page.</strong><br>An interest signup is not a booking. Each future class will state its format, access requirements, capacity and any price before registration.</div><section class="section-block"><h2>Learning that fits different lives.</h2><div class="cards three"><article class="panel"><p class="tag">Live online</p><h3>Classes &amp; webinars</h3><p>Scheduled sessions with a clear topic and space for questions. Recordings and accessibility arrangements will be stated per session.</p></article><article class="panel"><p class="tag">In person or hybrid</p><h3>Guided workshops</h3><p>Small-group practice where available. A venue is shared with registered participants; do not arrive without a confirmed booking.</p></article><article class="panel"><p class="tag">At your pace</p><h3>Lessons &amp; practice</h3><p>Videos, examples and exercises attached to a course. Homework supports the lesson without creating a separate community for every activity.</p></article></div></section><section class="section-block"><h2>Planned subjects</h2><ul class="simple-list"><li>Separate a source, an allegation, an inference and a finding.</li><li>Build a timeline while preserving uncertainty and attribution.</li><li>Test a tool with fictional records and reproducible feedback.</li><li>Trace how a correction should reach affected records and decisions.</li></ul><p><a href="/join/">Interested in teaching or contributing? Choose “Connect with Kapukai.”</a></p></section>''',False)
    page('community/about','About the Workshop','The Workshop connects Kapukai engineering tools, learning and carefully scoped contributions to public decision systems.', '''<div class="manage"><p class="eyebrow">About the Workshop</p><h1>Engineering people can inspect.</h1><p class="lede">Kapukai Governance Lab works on public decision systems: how records become classifications, obligations and consequential decisions, and how errors can be corrected.</p><h2>Our working order</h2><ol class="simple-list"><li>Safety, consent and control.</li><li>Successful participation.</li><li>Useful human connection.</li><li>Sustainable maintenance.</li><li>Learning and correction.</li><li>Growth that preserves those priorities.</li></ol><h2>What we offer</h2><p>Engineering tools, document organization and formatting, educational resources, research and model policy drafts. Any draft remains subject to the user’s review and decision about use. An attorney or public official may review it independently.</p><p>Kapukai is not a law firm and does not provide legal advice, representation or a guarantee of a legal result.</p><h2>How we learn</h2><p>Define the problem and scope. Identify stakeholders. Set priorities. Build a small, testable improvement. Measure useful outcomes, privacy comprehension and maintenance costs. Record what changed, then keep, adjust or reverse it.</p><p><a href="https://kapukai.org/founder/">Meet the founder</a> · <a href="/community/contact/">Contact the lab</a> · <a href="/community/status/">See current availability</a></p></div>''',False)
    page('community/contact','Contact and website directory','Contact Kapukai Governance Lab and find its public pages and current application addresses.', '''<p class="eyebrow">One place to find us</p><h1>Contact the lab.</h1><p class="lede">For questions about tools, learning, participation or your data: <a href="mailto:architect@kapukai.org">architect@kapukai.org</a>.</p><div class="notice">Please start with a general question. Do not send case files, identity documents, names of children or private addresses. In-person visits require a confirmed appointment.</div><div class="cards"><section class="panel"><h2>Find the right next step</h2><ul class="simple-list"><li><a href="/community/assistance/">Ask about free or discounted support</a></li><li><a href="/community/reviewers/">Apply as a reviewer or observation volunteer</a></li><li><a href="/join/">Choose class, volunteer or collaboration notices</a></li><li><a href="/community/privacy/">Request access, withdrawal or deletion assistance</a></li></ul></section><section class="panel"><h2>Visits and correspondence</h2><p>Contact <a href="mailto:architect@kapukai.org">architect@kapukai.org</a> for an appointment or mailing instructions before sending documents.</p><p class="small">Please do not arrive without a confirmed appointment or email private records without an agreed process.</p></section></div><section class="section-block"><h2>Website directory</h2><p>Kapukai.org is the main public address. Some tools currently use separate application addresses. An app address does not mean that every feature or paid offer is available; check the app’s current notice before use.</p><div class="table-wrap"><table><caption>Public pages and current application addresses</caption><thead><tr><th scope="col">Destination</th><th scope="col">Address</th><th scope="col">What to expect</th></tr></thead><tbody><tr><th scope="row">Kapukai Governance Lab</th><td><a href="https://kapukai.org/">kapukai.org</a></td><td>Main public website</td></tr><tr><th scope="row">Publications</th><td><a href="https://kapukai.org/pubs/">kapukai.org/pubs</a></td><td>Publications directory</td></tr><tr><th scope="row">First Circle</th><td><a href="https://kapukai.org/first-circle/">kapukai.org/first-circle</a></td><td>Existing participation page</td></tr><tr><th scope="row">The Workshop</th><td><a href="/community/">Workshop overview</a></td><td>Interest lists, applications and availability</td></tr><tr><th scope="row">AI intake</th><td><a href="https://kapukai-paid-intake.vercel.app/">kapukai-paid-intake.vercel.app</a></td><td>Separate application; see its access notice</td></tr><tr><th scope="row">Decision Integrity Bridge</th><td><a href="https://kapukai-decision-integrity-bridge.vercel.app/">kapukai-decision-integrity-bridge.vercel.app</a></td><td>Separate application; see its scope and status</td></tr></tbody></table></div></section>''',False)
    page('community/status','Service status and availability','Understand which Kapukai Workshop features are available, planned or subject to human review.', '''<p class="eyebrow">Clear expectations</p><h1>What is available?</h1><p class="lede">This is the Workshop’s feature availability guide, not a real-time uptime monitor. Check the response to a form before assuming a request was received.</p><div class="status-grid"><section class="panel"><span class="state-pill available">Available</span><h2>Learning &amp; interest lists</h2><ul class="simple-list"><li><a href="/community/practice/">Fictional practice cases</a> without signup.</li><li><a href="/articles/tort-law-and-accountability/">Public article</a> and source references.</li><li><a href="/join/">Separate email choices</a> for classes, volunteering, collaboration, testing and The Remedy Brief.</li><li>Email confirmation and withdrawal through your private link.</li></ul></section><section class="panel"><span class="state-pill">Subject to human review</span><h2>Applications</h2><ul class="simple-list"><li><a href="/community/assistance/">Free or discounted assistance</a>.</li><li><a href="/community/reviewers/">Reviewer or observation volunteer interest</a>.</li><li>Email confirmation starts human review; it does not grant service access.</li><li>Your private application link shows progress, structured requests, free resource offers, delivery, feedback and correction.</li><li><a href="/community/lifecycle/">Understand the application lifecycle</a>. Human decisions and capacity remain required.</li><li>Submission may be paused when capacity is unavailable. The form will tell you if it cannot accept a request.</li></ul></section><section class="panel"><span class="state-pill">Not open yet</span><h2>Member community</h2><ul class="simple-list"><li>Member accounts, profiles and discussion rooms.</li><li>Interest pools, mutual discovery and introductions.</li><li>Reviewer matching, shared calendars and case assignments.</li><li>Public feedback publication and expert credentials.</li></ul></section><section class="panel"><span class="state-pill">Coming later</span><h2>Classes &amp; guided work</h2><p>Dates, registration, learning materials and any course requirements will be announced separately. There are no confirmed events listed here.</p><a href="/community/learn/">Explore planned learning formats</a></section></div><div class="notice"><strong>Your choices remain separate.</strong><br>An application does not subscribe you to a newsletter, publish your profile or authorize case sharing. Private community discussion and public release require separate controls before they open.</div><p class="small">Availability guide updated October 8, 2026. For a failed request or data question, email <a href="mailto:architect@kapukai.org">architect@kapukai.org</a>.</p>''',False)
    page('community/apply','Your private application','Confirm, follow, respond to or withdraw your private Kapukai application.', '''<div class="manage"><p class="eyebrow">Your private application</p><h1>Your next step, clearly.</h1><div class="panel"><p id="application-manage-status" role="status" aria-live="polite">Checking this private link…</p><div id="application-details" hidden><dl id="application-summary"></dl><div class="actions"><button id="application-confirm" type="button" hidden>Confirm this application</button><button id="application-withdraw" class="button secondary" type="button" hidden>Withdraw this application</button></div><p class="small">Confirming asks for human review. It does not grant assistance, membership, an assignment or certification. Withdrawing affects only this application.</p><section id="application-lifecycle" class="divider" hidden></section></div></div><p><a href="/community/assistance/">Request assistance</a> · <a href="/community/reviewers/">Apply to contribute</a> · <a href="/community/contact/">Get help with your link</a></p><p class="small">Keep your confirmation email if you want to reopen this private link. This page removes the token from the address bar after opening.</p></div>''','applications.js')
    # Extend the existing privacy notice without changing the signup consent version or choices.
    from build_frontend import P
    privacy=P/'community/privacy/index.html'
    text=privacy.read_text()
    addition='''<section id="applications" class="divider"><h2>Assistance and contributor applications</h2><p>Application notice version: kapukai-applications-v1-2026-10-08.</p><p>The separate application form collects your email, optional alias, application type, selected service interest, requested support where relevant, optional broad professional category and availability, and your acknowledgements. It records request, confirmation and withdrawal information, structured preferences, human decisions, resource offers, delivery versions, receipt acknowledgements, feedback, correction requests and notification attempts so authorized operators can follow the work and document your choices.</p><p>We use your email to send the confirmation link and contact you about this application. Applying does not subscribe you to a newsletter, publish a profile or authorize sharing private case information. There is no automated decision about the merits of your situation. Confirmed applications wait for human review and available capacity.</p><p>Supabase stores the application records in Kapukai’s existing project. Postmark delivers application emails. Access is restricted to the service and authorized operators. Do not submit pay stubs, identity documents, case histories, private addresses or names of children. A legal name is not required. Use an alias without private details.</p><p>The confirmation link can confirm a request for 48 hours and manage this application for up to 180 days. After confirmation, the private page can show human review progress, ask for structured clarification, present a free nonbinding resource offer, acknowledge delivery, collect optional structured feedback, and receive correction or reconsideration requests. These choices and decision times form a private application history. Accepting an offer is not a purchase, contract, assignment, credential or public release. Feedback is not published, and no case narrative or file upload is accepted. Opening a link does not confirm an application. Withdrawal ends this application’s active review request; it does not erase necessary consent and audit history or change separate email subscriptions. Contact <a href="mailto:architect@kapukai.org">architect@kapukai.org</a> for access or deletion assistance. Separate onboarding and consent are required before any assignment or private record sharing.</p></section>'''
    text=text.replace('</main>',addition+'</main>')
    privacy.write_text(text)
